#!/usr/bin/env node
// Bundles supabase/migrations into a few SQL files that can be pasted into the
// Supabase SQL Editor when no terminal is available. Each part runs in one
// transaction and records its migrations in public.ledgerline_migrations with
// the same checksums as scripts/migrate.js, so later deployments (which run
// migrate.js) see them as applied and continue from there.
//
//   node scripts/bundle-migrations.js [outDir] [parts]     (default: dist/sql 4)
//
// Part 1 starts by removing an earlier, incomplete install (schema app). It
// refuses to do that if any account already exists.

import { createHash } from 'node:crypto';
import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const MIGRATIONS_DIR = path.join(ROOT, 'supabase/migrations');

const TRACKER = `create table if not exists public.ledgerline_migrations (
  version text primary key,
  name text not null,
  checksum text not null,
  applied_at timestamptz not null default now()
);`;

const RESET = `-- Remove an earlier, incomplete install — never a database with accounts.
do $guard$
declare
  n bigint;
begin
  if to_regclass('app.profiles') is not null then
    execute 'select count(*) from app.profiles' into n;
    if n > 0 then
      raise exception 'Ledgerline is already installed and has % account(s). Nothing was changed.', n;
    end if;
  end if;
end
$guard$;
drop schema if exists app cascade;
drop table if exists public.ledgerline_migrations;
${TRACKER}`;

function guard(partNo, previousVersion, firstVersion) {
  return `-- Part ${partNo} needs the previous part and must not run twice.
do $guard$
begin
  if to_regclass('public.ledgerline_migrations') is null then
    raise exception 'Run part ${partNo - 1} first.';
  end if;
  if not exists (select 1 from public.ledgerline_migrations where version = '${previousVersion}') then
    raise exception 'Run part ${partNo - 1} first.';
  end if;
  if exists (select 1 from public.ledgerline_migrations where version = '${firstVersion}') then
    raise exception 'Part ${partNo} is already installed. Nothing was changed.';
  end if;
end
$guard$;`;
}

export async function bundleMigrations({ outDir = path.join(ROOT, 'dist/sql'), parts = 4 } = {}) {
  const files = (await readdir(MIGRATIONS_DIR)).filter((f) => /^\d{14}_[a-z0-9_]+\.sql$/.test(f)).sort();
  const items = [];
  for (const file of files) {
    const body = await readFile(path.join(MIGRATIONS_DIR, file), 'utf8');
    items.push({ file, version: file.slice(0, 14), body, checksum: createHash('sha256').update(body).digest('hex') });
  }

  // Split in order into parts of similar size: each file goes to the part its
  // midpoint falls into.
  const total = items.reduce((n, i) => n + i.body.length, 0);
  const buckets = Array.from({ length: parts }, () => []);
  let offset = 0;
  for (const item of items) {
    const middle = offset + item.body.length / 2;
    buckets[Math.min(parts - 1, Math.floor((middle * parts) / total))].push(item);
    offset += item.body.length;
  }
  const groups = buckets.filter((b) => b.length);

  await mkdir(outDir, { recursive: true });
  const written = [];
  for (const [index, group] of groups.entries()) {
    const partNo = index + 1;
    const head = [
      `-- Ledgerline database install — part ${partNo} of ${groups.length}`,
      `-- Paste the whole file into Supabase → SQL Editor → Run. Then run part ${partNo + 1 <= groups.length ? partNo + 1 : '-'}.`,
      `-- Contains: ${group.map((g) => g.file).join(', ')}`,
      '-- Generated by scripts/bundle-migrations.js — do not edit by hand.',
      '',
      'begin;',
      '',
      partNo === 1 ? RESET : guard(partNo, groups[index - 1].at(-1).version, group[0].version),
      '',
    ];
    const body = group.map((g) => [
      `-- ════ ${g.file} ════`,
      g.body.trimEnd(),
      `insert into public.ledgerline_migrations (version, name, checksum) values ('${g.version}', '${g.file}', '${g.checksum}');`,
      '',
    ].join('\n'));
    const tail = ['commit;', '', `select 'part ${partNo} of ${groups.length} installed' as result;`, ''];
    const target = path.join(outDir, `ledgerline-install-part-${partNo}-of-${groups.length}.sql`);
    await writeFile(target, [...head, ...body, ...tail].join('\n'));
    written.push(target);
  }
  return written;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const outDir = process.argv[2] ? path.resolve(process.argv[2]) : undefined;
  const parts = process.argv[3] ? Number(process.argv[3]) : undefined;
  const written = await bundleMigrations({ outDir, parts });
  for (const f of written) console.log(`written ${path.relative(process.cwd(), f)}`);
}
